  def install
    venv = virtualenv_create(libexec, "python3.14")
    venv.pip_install resources
    venv.pip_install_and_link buildpath/"cli"
  end

  def caveats
    <<~EOS
      The CLI talks to a Prismis daemon. Add a [remote] section with its url
      and key to ~/.config/prismis/config.toml:

        [remote]
        url = "https://your-daemon-host:8989"
        key = "your-api-key"

      Check the connection with:

        prismis-cli list --limit 1
    EOS
  end

  test do
    system bin/"prismis-cli", "--help"
  end
end
